// Static figures for the explanation lessons, drawn natively in the page (same
// renderer and style as the live diagrams). Click a box to read about it.
// The README keeps its own SVG versions in docs/ (generated by docs/src).
import type { DNode, DEdge } from "./diagrams";

export type Figure = { title: string; w: number; h: number; nodes: DNode[]; edges: DEdge[] };
const N = (id: string, x: number, y: number, w: number, h: number, label: string, sub?: string, more: Partial<DNode> = {}): DNode =>
  ({ id, x, y, w, h, label, sub, layer: 0, ...more });
const G = (id: string, x: number, y: number, w: number, h: number, label: string, info?: string): DNode =>
  ({ id, x, y, w, h, label, layer: 0, kind: "group", info });

